        "signature": "OutsideArmyMgr.OnCameraMove",
        "sourceCode": "function cls:OnCameraMove()\r\n    if not mgr.unlockData:IsUnlock(CfgNs.FeatureUnlockEnum.NFUE_BattleHeadOptimization) then\r\n        return\r\n    end\r\n\r\n    if mgr.raidMap.IsInRaid then return end\r\n\r\n    local worldPos = mgr.mapVisual.CameraCtrl.cameraCtrl.CorePos\r\n    if self.lastCorePos then\r\n        local sqrMagnitude = (self.lastCorePos - worldPos).sqrMagnitude\r\n        if sqrMagnitude < CameraDirtyLength then\r\n            return\r\n        end\r\n    end\r\n\r\n    self.lastCorePos = worldPos\r\n\r\n    local curTime = mgr.time.realT\r\n    if curTime - (self.lastTime or 0) < 0.5 then\r\n        return\r\n    end\r\n    \r\n    self.lastTime = curTime\r\n\r\n    ProfilerUtil.BeginSample(\"OnCameraMove\")\r\n    local entityDict = mgr.mapCore.MapEntityCtrl.entitysByEntityId\r\n    local buckets = mgr.battleHead.waitShowEntityQueue.buckets\r\n    for i = 2, #buckets do -- 最高优先级不受摄像机位置影响\r\n        for entityId, _ in pairs(buckets[i]) do\r\n            (entityDict[entityId])?:RefreshDistancePriority()\r\n        end\r\n    end\r\n\r\n    buckets = mgr.battleHead.battleHeadQueue.buckets\r\n    for i = 1, #buckets do \r\n        for entityId, _ in pairs(buckets[i]) do\r\n            (entityDict[entityId])?:RefreshDistancePriority()\r\n        end\r\n    end\r\n\r\n    ProfilerUtil.EndSample()\r\nend\r",
